/**
 * Unit tests for posttool/design-import/auto-verify (#1386, sweep T1).
 *
 * CC sends tool_input.skill as `ork:design-import` (plugin prefix included)
 * and the tool result as `tool_response`, not `tool_output`. Both the bare
 * name match and the tool_output read meant this hook never fired on a real
 * payload.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, rmSync, mkdirSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { postDesignImportAutoVerify } from '../../../posttool/design-import/auto-verify.js';
import { createTestContext } from '../../fixtures/test-context.js';
import type { HookInput } from '../../../types.js';

let workspace: string;
let testCtx: ReturnType<typeof createTestContext>;

beforeEach(() => {
  workspace = mkdtempSync(join(tmpdir(), 'ork-autoverify-'));
  testCtx = createTestContext();
});

afterEach(() => {
  try {
    rmSync(workspace, { recursive: true, force: true });
  } catch {
    /* best-effort */
  }
});

function makeSkillInput(
  skill: string,
  toolResponse: unknown,
  projectDir = workspace,
): HookInput {
  return {
    tool_name: 'Skill',
    session_id: 'sid-test',
    tool_input: { skill } as Record<string, unknown>,
    tool_response: toolResponse,
    project_dir: projectDir,
  };
}

function contextOf(result: Awaited<ReturnType<typeof postDesignImportAutoVerify>>): string {
  const out = result.hookSpecificOutput as { additionalContext?: string } | undefined;
  return out?.additionalContext ?? '';
}

describe('postDesignImportAutoVerify', () => {
  it('fires on the real CC payload: skill "ork:design-import" + tool_response string', async () => {
    const r = await postDesignImportAutoVerify(
      makeSkillInput('ork:design-import', 'Imported bundle bundle-123\n3 components written'),
      testCtx,
    );
    expect(contextOf(r)).toContain('/ork:expect');
  });

  it('fires on the bare skill name too (legacy callers)', async () => {
    const r = await postDesignImportAutoVerify(
      makeSkillInput('design-import', 'Imported bundle bundle-123'),
      testCtx,
    );
    expect(contextOf(r)).toContain('/ork:expect');
  });

  it('still reads the legacy tool_output alias when tool_response is absent', async () => {
    const input = makeSkillInput('ork:design-import', undefined);
    input.tool_output = 'Imported bundle bundle-123';
    const r = await postDesignImportAutoVerify(input, testCtx);
    expect(contextOf(r)).toContain('/ork:expect');
  });

  it('references the newest provenance file when one exists', async () => {
    const handoffs = join(workspace, '.claude', 'design-handoffs');
    mkdirSync(handoffs, { recursive: true });
    writeFileSync(join(handoffs, 'bundle-abc.json'), '{}');
    const r = await postDesignImportAutoVerify(
      makeSkillInput('ork:design-import', 'Imported bundle bundle-abc'),
      testCtx,
    );
    expect(contextOf(r)).toContain('bundle-abc');
  });

  it('stays silent for other skills', async () => {
    const r = await postDesignImportAutoVerify(
      makeSkillInput('ork:expect', 'Imported bundle bundle-123'),
      testCtx,
    );
    expect(r.hookSpecificOutput).toBeUndefined();
  });

  it('stays silent when the import produced no manifest', async () => {
    const r = await postDesignImportAutoVerify(
      makeSkillInput('ork:design-import', 'design-import failed: bad bundle'),
      testCtx,
    );
    expect(r.hookSpecificOutput).toBeUndefined();
  });
});
